#include "dac.h"
#include "hw_dac.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void dac_wr_voltage (double voltage)
{
	UInt16 write_value = 0 ;

	if (voltage > 9.9)
		return ;
	
	if (voltage < 5)	
		write_value = (UInt16)((voltage / 9.9) * 1023) ;
	else
		write_value = (UInt16)((voltage / 10) * 1023) ;

 	dac_wr_value (write_value,FALSE) ;
}



